DIALOGS = [
[trp_sod_strategy_advisor, "sa_select_ranged_cavalry2", [
	(eq, "$g_sod_sa_talk_subject", 4),
	], "But I digress; the Legion hires cavalry mercenaries who call themselves the 'Sons of Deer'.  The Sons of Deer have historical ties to the Zerrikanians but for some reason or another they allied with the Legion betraying the Zerrikanians and helped drive them from their land.  The Legion is smart enough to realize that sometimes you have to fight fire with fire.  Do not expect any weaknesses in their troop structure, they have a counter to every unit we can throw at them.  We have to be smarter, or depend on something greater than us mere mortals to defeat them.", "sa_select_ranged_cavalry3", []],
]
